use biome_formatter_test::spec::{SpecSnapshot, SpecTestFile};
use biome_js_formatter::context::JsFormatOptions;
use biome_js_syntax::{JsFileSource, ModuleKind};
use std::path::Path;

mod language {
    include!("language.rs");
